package mihon.core.dictionary.corpus

/**
 * Minimal, dependency-free JSON reader used only by the *test* classpath.
 *
 * `:core:dictionary` declares no JSON library and its build file is frozen (contract §3.2), so
 * the corpus test cannot pull one in. The corpus is machine-generated by
 * `tools/yomitan-corpus/build.mjs`, so a small recursive-descent parser is enough to prove the
 * committed `.jsonl`/`manifest.json` are well-formed and to inspect their structure.
 *
 * Supports objects, arrays, strings (with escapes and `\uXXXX`), numbers, booleans and `null`.
 * Objects become [LinkedHashMap], arrays become [ArrayList], integers become [Long] and
 * non-integers [Double].
 */
internal object Json {

    fun parse(text: String): Any? = Parser(text).parseDocument()

    private class Parser(private val text: String) {
        private var index = 0

        fun parseDocument(): Any? {
            val value = parseValue()
            skipWhitespace()
            check(index == text.length) { "unexpected trailing content at index $index" }
            return value
        }

        private fun parseValue(): Any? {
            skipWhitespace()
            require(index < text.length) { "unexpected end of input" }
            return when (text[index]) {
                '{' -> parseObject()
                '[' -> parseArray()
                '"' -> parseString()
                't' -> {
                    expect("true")
                    true
                }
                'f' -> {
                    expect("false")
                    false
                }
                'n' -> {
                    expect("null")
                    null
                }
                else -> parseNumber()
            }
        }

        private fun parseObject(): Map<String, Any?> {
            expect("{")
            val result = LinkedHashMap<String, Any?>()
            skipWhitespace()
            if (peek() == '}') {
                index++
                return result
            }
            while (true) {
                skipWhitespace()
                val key = parseString()
                skipWhitespace()
                expect(":")
                result[key] = parseValue()
                skipWhitespace()
                when (val delimiter = next()) {
                    ',' -> continue
                    '}' -> return result
                    else -> error("expected ',' or '}' at index ${index - 1} but found '$delimiter'")
                }
            }
        }

        private fun parseArray(): List<Any?> {
            expect("[")
            val result = ArrayList<Any?>()
            skipWhitespace()
            if (peek() == ']') {
                index++
                return result
            }
            while (true) {
                result.add(parseValue())
                skipWhitespace()
                when (val delimiter = next()) {
                    ',' -> continue
                    ']' -> return result
                    else -> error("expected ',' or ']' at index ${index - 1} but found '$delimiter'")
                }
            }
        }

        private fun parseString(): String {
            expect("\"")
            val builder = StringBuilder()
            while (true) {
                when (val char = next()) {
                    '"' -> return builder.toString()
                    '\\' -> when (val escape = next()) {
                        '"' -> builder.append('"')
                        '\\' -> builder.append('\\')
                        '/' -> builder.append('/')
                        'b' -> builder.append('\b')
                        'f' -> builder.append('\u000C')
                        'n' -> builder.append('\n')
                        'r' -> builder.append('\r')
                        't' -> builder.append('\t')
                        'u' -> builder.append(readUnicodeEscape())
                        else -> error("invalid escape '\\$escape' at index ${index - 1}")
                    }
                    else -> builder.append(char)
                }
            }
        }

        private fun readUnicodeEscape(): Char {
            require(index + 4 <= text.length) { "truncated unicode escape at index $index" }
            val hex = text.substring(index, index + 4)
            index += 4
            return hex.toInt(16).toChar()
        }

        private fun parseNumber(): Any {
            val start = index
            if (peek() == '-') index++
            while (index < text.length && text[index].isNumberChar()) index++
            val literal = text.substring(start, index)
            require(literal.isNotEmpty()) { "invalid number at index $start" }
            return if (literal.any { it == '.' || it == 'e' || it == 'E' }) {
                literal.toDouble()
            } else {
                literal.toLongOrNull() ?: literal.toDouble()
            }
        }

        private fun Char.isNumberChar(): Boolean =
            isDigit() || this == '.' || this == 'e' || this == 'E' || this == '+' || this == '-'

        private fun skipWhitespace() {
            while (index < text.length && text[index].isWhitespace()) index++
        }

        private fun peek(): Char? = if (index < text.length) text[index] else null

        private fun next(): Char {
            require(index < text.length) { "unexpected end of input" }
            return text[index++]
        }

        private fun expect(literal: String) {
            require(text.startsWith(literal, index)) { "expected '$literal' at index $index" }
            index += literal.length
        }
    }
}
